head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getColumnEditFormat]<br/>Body Column 정보를 사용하여 특정 Column 의 editFormat 속성값을 반환합니다.",
    "validation" : [
        "Row 가 MultiLine 이어도 모든 Column 은 고유의 인덱스값을 가지며 해당 인덱스로 editFormat 속성값을 조회할 수 있어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Row 가 2줄(MultiLine) 로 구성된 그리드. 1줄=txtFmt1(text, editFormat=####/##/##, 고유 인덱스 0)/txtA(text, 1), 2줄=txtFmt2(text, editFormat=##-##-####, 고유 인덱스 2)/txtB(text, 3). MultiLine 이어도 2줄의 txtFmt2 는 인덱스 1 이 아니라 고유 인덱스 2 로 조회됨.\n[절차] columnInfo(인덱스) 선택 후 (getColumnEditFormat 실행) 클릭.\n[확인] 0=####/##/## / 2=##-##-####(2줄 고유 인덱스) / 99=false(유효하지않음) 가 반환영역에 출력됨."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="txtFmt1" name="txtFmt1" dataType="text"></w2:column>';
    strDlt += '<w2:column id="txtA" name="txtA" dataType="text"></w2:column>';
    strDlt += '<w2:column id="txtFmt2" name="txtFmt2" dataType="text"></w2:column>';
    strDlt += '<w2:column id="txtB" name="txtB" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "txtFmt1": "20260101", "txtA": "노트북", "txtFmt2": "20260201", "txtB": "블랙" },
        { "txtFmt1": "20260102", "txtA": "모니터", "txtFmt2": "20260202", "txtB": "화이트" },
        { "txtFmt1": "20260103", "txtA": "키보드", "txtFmt2": "20260203", "txtB": "실버" },
        { "txtFmt1": "20260104", "txtA": "마우스", "txtFmt2": "20260204", "txtB": "그레이" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 : Row 를 2줄(MultiLine) 로 구성
    //  - 1줄 : txtFmt1(text, editFormat=####/##/##, 고유 인덱스 0) / txtA(text, 1)
    //  - 2줄 : txtFmt2(text, editFormat=##-##-####, 고유 인덱스 2) / txtB(text, 3)
    //  - Row 가 MultiLine 이어도 모든 Column 은 고유 인덱스(0~3)를 가짐
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:520px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="getColumnEditFormat 테스트 그리드(MultiLine)"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="240" style="" inputType="text" id="hcol1" value="일자1(text editFormat=####/##/##)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol2" value="품목(text)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="240" style="" inputType="text" id="hcol3" value="일자2(text editFormat=##-##-####)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol4" value="색상(text)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    // index 0 : txtFmt1 (text, editFormat=####/##/##)
    strTarget += '<w2:column width="240" style="" inputType="text" editFormat="####/##/##" editPlaceholderChar="_" id="txtFmt1" dataList="txtFmt1"></w2:column>';
    // index 1 : txtA (text)
    strTarget += '<w2:column width="*" style="" inputType="text" id="txtA" dataList="txtA"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="brow2">';
    // index 2 : txtFmt2 (text, editFormat=##-##-####) - MultiLine 2줄 고유 인덱스 2
    strTarget += '<w2:column width="240" style="" inputType="text" editFormat="##-##-####" editPlaceholderChar="_" id="txtFmt2" dataList="txtFmt2"></w2:column>';
    // index 3 : txtB (text)
    strTarget += '<w2:column width="*" style="" inputType="text" id="txtB" dataList="txtB"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// getColumnEditFormat 조회 (MultiLine 고유 인덱스 기반)
//  - Row 가 2줄(MultiLine) 이어도 모든 Column 은 고유 인덱스(0~3)를 가짐
//  - 2줄의 txtFmt2 는 인덱스 1 이 아니라 고유 인덱스 2 로 조회됨
//  - 0=####/##/## / 2=##-##-#### / 99=false
scwin.btn_getColumnEditFormat_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());

    let result = target1.getColumnEditFormat(columnInfo);

    wf_body_bottom.getObj("scwin").setReturnValue("getColumnEditFormat(" + columnInfo + ") -> 반환값: " + result);
}
